package dev.zomboid.lootvalidation;
import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.gametest.*;import net.minecraft.gametest.framework.*;import net.minecraft.resources.*;import net.minecraft.core.registries.Registries;import net.minecraft.core.component.DataComponents;import net.minecraft.world.item.*;import net.minecraft.world.level.storage.loot.*;import net.minecraft.world.level.storage.loot.parameters.*;import net.minecraft.world.phys.Vec3;import dev.zomboid.remains.*;
@Mod("loot_validation") @GameTestHolder("loot_validation") @PrefixGameTestTemplate(false)
public final class Checks {
 @GameTest(template="port_empty") public static void gunsAndAmmo(GameTestHelper h){for(var s:AddonCatalog.GUNS){ItemStack stack=AddonDrops.gun(s,5);h.assertTrue(!stack.isEmpty(),"Gun base missing");var gun=com.tacz.guns.api.item.IGun.getIGunOrNull(stack);h.assertTrue(gun!=null&&gun.getGunId(stack).toString().equals(s.id()),"Wrong gun ID "+s.id());h.assertTrue(gun.getCurrentAmmoCount(stack)<=s.capacity(),"Overfilled gun");h.assertTrue(com.tacz.guns.api.TimelessAPI.getCommonGunIndex(ResourceLocation.parse(s.id())).isPresent(),"Pack gun index absent "+s.id());var ammo=AddonDrops.ammo(s.ammo(),16);h.assertTrue(ammo.get(DataComponents.CUSTOM_DATA).copyTag().getString("AmmoId").equals(s.ammo()),"Wrong ammo");}h.succeed();}
 @GameTest(template="port_empty") public static void lootTables(GameTestHelper h){var p=new LootParams.Builder(h.getLevel()).withParameter(LootContextParams.ORIGIN,Vec3.ZERO).create(LootContextParamSets.CHEST);for(var s:AddonCatalog.GUNS){var key=ResourceKey.create(Registries.LOOT_TABLE,ResourceLocation.fromNamespaceAndPath("mosslorn","addons/loadouts/"+s.id().replace(':','_')));var loot=new java.util.ArrayList<ItemStack>();h.getLevel().getServer().reloadableRegistries().getLootTable(key).getRandomItemsRaw(p,loot::add);h.assertTrue(loot.size()==2,"Gun plus ammo expected for "+s.id()+" got "+loot.size()+" "+loot);h.assertTrue(loot.stream().anyMatch(i->i.get(DataComponents.CUSTOM_DATA)!=null&&i.get(DataComponents.CUSTOM_DATA).copyTag().getString("GunId").equals(s.id())),"Loot gun ID missing");}var armor=h.getLevel().getServer().reloadableRegistries().getLootTable(ResourceKey.create(Registries.LOOT_TABLE,ResourceLocation.fromNamespaceAndPath("mosslorn","addons/armor_police"))).getRandomItems(p);h.assertTrue(armor.size()==1&&net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(armor.getFirst().getItem()).getNamespace().equals("lrarmor"),"Armor loot missing");h.succeed();}
 @GameTest(template="port_empty") public static void expandingCorpse(GameTestHelper h)throws Exception{Class<?> d=Class.forName("dev.zomboid.remains.ZombieRemainsLoot$CorpseData"),c=Class.forName("dev.zomboid.remains.ZombieRemainsLoot$Corpse");Object data=d.getDeclaredConstructor().newInstance();var ctor=java.util.Arrays.stream(c.getDeclaredConstructors()).filter(k->k.getParameterCount()==3).findFirst().orElseThrow();ctor.setAccessible(true);Object corpse=ctor.newInstance(data,"minecraft:stone",false);var f=c.getDeclaredField("inventory");f.setAccessible(true);var inv=(net.minecraft.world.SimpleContainer)f.get(corpse);int old=inv.getContainerSize();for(int i=0;i<old;i++)inv.setItem(i,new ItemStack(Items.DIAMOND,64));AddonDrops.insert(corpse,new ItemStack(Items.IRON_INGOT,12));h.assertTrue(inv.getContainerSize()==old+9,"Full corpse must grow one row");h.assertTrue(inv.countItem(Items.IRON_INGOT)==12,"Loot lost");h.succeed();}
 @GameTest(template="port_empty") public static void attachmentIds(GameTestHelper h)throws Exception{for(String id:AddonCatalog.ATTACHMENTS){var stack=AddonDrops.attachment(id);h.assertTrue(!stack.isEmpty(),"Attachment base missing");Object actual=Class.forName("com.tacz.guns.api.item.IAttachment").getMethod("getAttachmentId",ItemStack.class).invoke(stack.getItem(),stack);h.assertTrue(actual.toString().equals(id),"Attachment ID mismatch");}h.succeed();}
}
